base_w = 120;
base_d = 110;
base_h = 42;
pan_r = 32;
pan_h = 18;
mast_w = 16;
mast_d = 28;
mast_h = 78;
cradle_w = 72;
cradle_d = 20;
cradle_h = 12;

module base_plate() {
    difference() {
        hull() {
            translate([-base_w/2 + 12, -base_d/2 + 12, 0]) cylinder(h = base_h, r = 12, $fn = 48);
            translate([ base_w/2 - 12, -base_d/2 + 12, 0]) cylinder(h = base_h, r = 12, $fn = 48);
            translate([-base_w/2 + 12,  base_d/2 - 12, 0]) cylinder(h = base_h, r = 12, $fn = 48);
            translate([ base_w/2 - 12,  base_d/2 - 12, 0]) cylinder(h = base_h, r = 12, $fn = 48);
        }
        translate([0, 0, 6]) cube([70, 50, 26], center = true);
    }
}

module pan_stage() {
    translate([0, 0, base_h]) cylinder(h = pan_h, r = pan_r, $fn = 64);
}

module mast() {
    translate([-mast_w/2, -mast_d/2, base_h + pan_h]) cube([mast_w, mast_d, mast_h]);
}

module tilt_cradle() {
    translate([-cradle_w/2, -cradle_d/2, base_h + pan_h + mast_h]) cube([cradle_w, cradle_d, cradle_h]);
}

module sensor_mount() {
    translate([-26, -10, base_h + pan_h + mast_h + cradle_h]) cube([52, 20, 18]);
}

base_plate();
pan_stage();
mast();
tilt_cradle();
sensor_mount();

