#include <Servo.h>
#include <SoftwareSerial.h>

const int panPin = 9;
const int tiltPin = 10;
const int trigPin = 6;
const int echoPin = 7;
const int ledPin = 13;
const int voiceRxPin = 2;
const int voiceTxPin = 3;

Servo panServo;
Servo tiltServo;
SoftwareSerial voiceSerial(voiceRxPin, voiceTxPin);

int panAngle = 90;
int tiltAngle = 85;
unsigned long lastSweepStep = 0;
bool trackingEnabled = true;

long readDistanceCm() {
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);
  long duration = pulseIn(echoPin, HIGH, 25000);
  if (duration == 0) {
    return -1;
  }
  return duration / 58;
}

void clampAndWrite() {
  panAngle = constrain(panAngle, 15, 165);
  tiltAngle = constrain(tiltAngle, 35, 140);
  panServo.write(panAngle);
  tiltServo.write(tiltAngle);
}

void handleVoiceCommand(char command) {
  if (command == 'T') {
    trackingEnabled = true;
    digitalWrite(ledPin, HIGH);
  } else if (command == 'H') {
    trackingEnabled = false;
    digitalWrite(ledPin, LOW);
  } else if (command == 'S') {
    panAngle = 45;
    tiltAngle = 90;
    clampAndWrite();
  }
}

void setup() {
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
  pinMode(ledPin, OUTPUT);
  panServo.attach(panPin);
  tiltServo.attach(tiltPin);
  voiceSerial.begin(9600);
  Serial.begin(115200);
  clampAndWrite();
}

void loop() {
  if (voiceSerial.available()) {
    handleVoiceCommand((char)voiceSerial.read());
  }

  long distanceCm = readDistanceCm();
  if (distanceCm < 0) {
    delay(40);
    return;
  }

  if (trackingEnabled) {
    if (distanceCm < 20) {
      tiltAngle += 1;
    } else if (distanceCm > 45) {
      tiltAngle -= 1;
    }

    if (millis() - lastSweepStep > 120) {
      panAngle += 2;
      if (panAngle > 150) {
        panAngle = 30;
      }
      lastSweepStep = millis();
    }
    clampAndWrite();
  }

  delay(30);
}
